using System;using System.Data;using System.Data.SqlClient;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class InterviewScorecardPage:UserControl{ComboBox interview,recommendation;NumericUpDown technical,communication,culture;TextBox comments;DataGridView grid;public InterviewScorecardPage(){if(!AppSession.Can("Applications.Manage")){Controls.Add(Ui.Label(L.Fa?"دسترسی ندارید":"Access denied",16,true));return;}Dock=DockStyle.Fill;var form=Ui.Card();form.Dock=DockStyle.Top;form.Height=150;interview=new ComboBox{Width=280,DropDownStyle=ComboBoxStyle.DropDownList};technical=Score();communication=Score();culture=Score();recommendation=new ComboBox{Width=140,DropDownStyle=ComboBoxStyle.DropDownList};recommendation.Items.AddRange(new object[]{"Strong Hire","Hire","Hold","No Hire"});recommendation.SelectedIndex=1;comments=Ui.Text();comments.Width=260;var save=Ui.Button(L.Fa?"ثبت ارزیابی":"Save scorecard");save.Click+=(s,e)=>Save();var f=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true};f.Controls.AddRange(new Control[]{interview,Ui.Label(L.Fa?"فنی":"Technical"),technical,Ui.Label(L.Fa?"ارتباط":"Communication"),communication,Ui.Label(L.Fa?"فرهنگ سازمانی":"Culture"),culture,recommendation,comments,save});form.Controls.Add(f);grid=Ui.Grid();Controls.Add(grid);Controls.Add(form);LoadInterviews();LoadRows();}NumericUpDown Score(){return new NumericUpDown{Minimum=1,Maximum=10,Value=5,Width=60};}void LoadInterviews(){var t=Database.Query("SELECT i.Id,CONCAT(c.FullName,N' - ',j.Title,N' - ',CONVERT(nvarchar(16),i.ScheduledAt,120)) DisplayName FROM Interviews i JOIN Applications a ON a.Id=i.ApplicationId JOIN Candidates c ON c.Id=a.CandidateId JOIN Jobs j ON j.Id=a.JobId ORDER BY i.ScheduledAt DESC");interview.DataSource=t;interview.DisplayMember="DisplayName";interview.ValueMember="Id";}void Save(){if(interview.SelectedValue==null)return;Database.Exec("INSERT InterviewScorecards(InterviewId,TechnicalScore,CommunicationScore,CultureScore,Recommendation,Comments,CreatedBy) VALUES(@i,@t,@c,@u,@r,@m,@by)",new SqlParameter("@i",interview.SelectedValue),new SqlParameter("@t",technical.Value),new SqlParameter("@c",communication.Value),new SqlParameter("@u",culture.Value),new SqlParameter("@r",recommendation.Text),new SqlParameter("@m",comments.Text),new SqlParameter("@by",AppSession.UserId));Database.Audit("Create","InterviewScorecard",recommendation.Text);LoadRows();}void LoadRows(){grid.DataSource=Database.Query("SELECT s.Id,c.FullName Candidate,j.Title Job,s.TechnicalScore,s.CommunicationScore,s.CultureScore,s.Recommendation,s.CreatedAt FROM InterviewScorecards s JOIN Interviews i ON i.Id=s.InterviewId JOIN Applications a ON a.Id=i.ApplicationId JOIN Candidates c ON c.Id=a.CandidateId JOIN Jobs j ON j.Id=a.JobId ORDER BY s.Id DESC");}}}
